import importlib.util,json
from pathlib import Path
p=Path(__file__).with_name('run_worker.py');spec=importlib.util.spec_from_file_location('replacement_worker',p);w=importlib.util.module_from_spec(spec);spec.loader.exec_module(w)
existing=json.loads((w.R.parent/'cross-plan-input.json').read_text())+json.loads((w.R/'scenario-plan.json').read_text())['plans'];compact=[{k:v for k,v in x.items() if k in ['group','scenario','premise','mechanism','memory_focus']} for x in existing]
prompt='''No tools. Produce exactly4 NEW replacement plans, IDs c_replace_041..044, families grounding or language_explanation only. Earlier4 passive observation conversations failed for repetition, do not reuse them. Each new plan must sustain4 or5 short meaningful exchanges as grounded English discussion, no artificial repeated comprehension quiz and no advice/coaching. Concrete user-provided texts must appear in generated dialogue; hidden plan never evidence. No maths/tools/medical/legal/science specialist assertions. Distinct from ALL supplied1040plans: avoid exact same semantic puzzle merely different nouns. Prioritize useful basic English response interpretation, punctuation/phrasing or discourse pragmatics in concrete contexts, with explicit user-led application. Return schema JSON only.\nEXISTING:\n'''+json.dumps(compact,ensure_ascii=False)
d,raw=w.cli('four-plan',prompt,w.R/'plan-schema.json');assert len(d['scenarios'])==4;print('fournewplans',flush=True)
